// ============================================================================
// 2. Era helper
// ============================================================================

export type Era = "early" | "mid" | "late" | "modern";

export function getEra(year: number): Era {
  if (year < 1990) return "early";
  if (year < 1996) return "mid";
  if (year < 2006) return "late";
  return "modern";
}

