      topic: "CAR BROKE DOWN EN ROUTE TO THE PARTY: SCENE SAVIOR STORIES",
      year: 1995,
      month: 6,
      actorId: "trix_art",
      messages: [
        { sender: "Hype", text: "My car's alternator died 50km from Assembly 93. A Finnish scener picked us up in a van with 6 other coders. We made it just in time for the compo deadline. The scene takes care of its own.", color: "text-amber-400" },
        { sender: "Vectra", text: "Stranded at a gas station in rural Sweden at 3am with a dead battery. A sysop from a local BBS node recognized my handle and jumped my car. BBS networks save lives.", color: "text-rose-300" },
        { sender: "FlameAlchemist", text: "Your car breaking down is a sign. The demo gods do not want you to compete. Listen to them and stay home. I once missed a party and the winning demo was terrible. Fate is real.", color: "text-orange-400" },
      ],
      interacted: false,
      playerActionTaken: null,
      dramaFinished: false,
      choices: [
        { text: "The scene community is the best safety net. We help each other get to parties.", type: "support", effectDescription: "+20 Reputation, +5 Friendship with Hype" },
        { text: "If you can't handle the logistics of a road trip, you can't handle a compo.", type: "flame", effectDescription: "+5 Reputation (tough love)" },
      ],
