      board: "PIXEL_PERFECTION",
      topic: "PROCEDURAL TEXTURE TECHNIQUES: BEYOND PERLIN NOISE",
      year: 2001,
      month: 1,
      actorId: "purple_motion",
      messages: [
        { sender: "Chaos", text: "Perlin noise is the 'hello world' of procedural texturing. Real pros use Worley noise, Gabor noise, and cellular automata. A palette of 3 noise types can generate infinite variety.", color: "text-[#a855f7]" },
        { sender: "Trix", text: "Domain warping a simple noise function produces textures that look hand-painted. Apply 2 layers of FBM noise, warp the coordinates with a third layer, and the result is pure alchemy.", color: "text-[#c084fc]" },
        { sender: "RasterRat", text: "Procedural textures in 64K intros are the highest form of pixel art. No samples, no external assets, just math and palette. Every pixel is intentionally generated.", color: "text-rose-400" },
      ],
      interacted: false,
      playerActionTaken: null,
      dramaFinished: false,
      choices: [
        { text: "Domain warping is the secret sauce. Layer noise like a pro.", type: "support", effectDescription: "+20 research points, +10 Reputation" },
        { text: "Hand-drawn pixel art has more soul than any procedural generation.", type: "flame", effectDescription: "+10 Reputation (traditionalist stance)" },
      ],
      infoType: "technical_discovery",
