      topic: "SIZECODING CHALLENGE: 256 BYTE INTRO COMPO NEXT MONTH",
      year: 1997,
      month: 9,
      actorId: "trix_art",
      messages: [
        { sender: "Chaos", text: "256 bytes for a demo. No external data, no samples, no libraries. Pure bootable binary. The only tools allowed are a hex editor and raw determination.", color: "text-[#a855f7]" },
        { sender: "CrashOverride", text: "I managed to fit a starfield, a sine scroller, and 4-channel audio in 248 bytes on the C64. The trick is reusing every register as a counter and every byte as multiple instructions.", color: "text-purple-400" },
        { sender: "ByteWizard", text: "Sizecoding is the purest form of demoscene programming. Every byte is a decision. Every optimization is a discovery. The 256-byte compo is harder than any 64K compo and twice as rewarding.", color: "text-blue-300" },
      ],
      interacted: false,
      playerActionTaken: null,
